export function locations() {
  return KALAS_LOCATIONS.map((l) => ({ ...l }));
}

export function locationById(id) {
  return KALAS_LOCATIONS.find((l) => l.id === id) || null;
}

export function locationsByType(type) {
  return KALAS_LOCATIONS.filter((l) => l.type === type).map((l) => ({ ...l }));
}

export function npcs() {
  return KALAS_NPCS.map((n) => ({ ...n }));
}

export function npcsAtLocation(locationId) {
  return KALAS_NPCS.filter((n) => n.locationId === locationId).map((n) => ({ ...n }));
}

export function factions() {
  return KALAS_FACTIONS.map((f) => ({ ...f }));
}

export function trades() {
  return [...KALAS_TRADES];
}

export function hooks() {
  return KALAS_HOOKS.map((h) => ({ ...h }));
}
